import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('validates against the schema captured at register time, not at execute time', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register({name: 'get_weather', description: 'Get weather', inputSchema: schema}, async () => {
      calls++;
      return 'sunny';
    });

    // Mutate the schema after registration — the compiled validator must not be affected.
    schema['required'] = [];

    const response = await registry.execute('get_weather', {});

    expect({calls, rejected: /required/i.test(response.result)}).toEqual({calls: 0, rejected: true});
  });
});

